import sys, os
sys.path.insert(0, '.')
from gen_lib import make, APP

OK = 0

def gen(slug, name, code, capital, currency, lang, langCode,
        title, meta_desc, og_desc, market,
        g1, g2, g3, bb, bbd, btxt, rank, sect, trust, stats,
        hl, hp, hc, hr,
        t1t, t1d, t2t, t2d, t3t, t3d,
        e1t, e1d, e2t, e2d, e3t, e3d, e4t, e4d,
        f1q, f1a, f2q, f2a, f3q, f3a, f4q, f4a, f5q, f5a,
        cta, kw, eco_h, eco_s, why_h, why_t, top_h, top_s, guide_h, bread):
    
    page = make(
        slug=slug, name=name, code=code, capital=capital, currency=currency,
        lang=lang, langCode=langCode,
        title=title, meta_desc=meta_desc, og_desc=og_desc, market=market,
        grad1=g1, grad2=g2, grad3=g3,
        badge_bg=bb, badge_border=bbd, badge_text=btxt,
        rank_col=rank, section_col=sect, trust_col=trust, stats_filter=stats,
        hero_lang=hl, hero_price=hp, hero_comply=hc, hero_ready=hr,
        trust1_t=t1t, trust1_d=t1d, trust2_t=t2t, trust2_d=t2d, trust3_t=t3t, trust3_d=t3d,
        eco1_t=e1t, eco1_d=e1d, eco2_t=e2t, eco2_d=e2d, eco3_t=e3t, eco3_d=e3d, eco4_t=e4t, eco4_d=e4d,
        faq1_q=f1q, faq1_a=f1a, faq2_q=f2q, faq2_a=f2a, faq3_q=f3q, faq3_a=f3a, faq4_q=f4q, faq4_a=f4a, faq5_q=f5q, faq5_a=f5a,
        cta_line=cta, keywords=kw,
        eco_heading=eco_h, eco_sub=eco_s,
        why_heading=why_h, why_text=why_t,
        top_heading=top_h, top_sub=top_s,
        guide_heading=guide_h, breadcrumb_name=bread)
    
    canada_left = page.count('Canada')
    if canada_left > 0:
        print(f"ERROR: {slug} has {canada_left} Canada references!")
        return False
    
    outdir = os.path.join(APP, f'ai-tools-{slug}')
    os.makedirs(outdir, exist_ok=True)
    with open(os.path.join(outdir, 'page.tsx'), 'w') as pf:
        pf.write(page)
    
    global OK
    OK += 1
    print(f"OK ({OK}): {slug}")
    return True

